-- Native PostgreSQL schema. SQLite is supported only during the migration window.

CREATE TABLE metadata(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,key TEXT PRIMARY KEY,value TEXT NOT NULL);

CREATE TABLE admin(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id BIGINT PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,password TEXT NOT NULL,must_change BIGINT NOT NULL DEFAULT 1);

CREATE TABLE sessions(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,hash TEXT PRIMARY KEY,csrf TEXT NOT NULL,expires BIGINT NOT NULL);

CREATE TABLE nodes(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,config TEXT NOT NULL,password TEXT NOT NULL DEFAULT '',password_expires BIGINT NOT NULL DEFAULT 0,agent_hash TEXT NOT NULL UNIQUE,agent_secret TEXT NOT NULL,desired_revision BIGINT NOT NULL DEFAULT 1,applied_revision BIGINT NOT NULL DEFAULT 0,last_seen BIGINT NOT NULL DEFAULT 0,metrics TEXT NOT NULL DEFAULT '{}',online TEXT NOT NULL DEFAULT '{}',core_healthy BIGINT NOT NULL DEFAULT 0, deleted_at BIGINT NOT NULL DEFAULT 0, lifecycle TEXT NOT NULL DEFAULT 'active', revision BIGINT NOT NULL DEFAULT 1, managed BIGINT NOT NULL DEFAULT 0, capabilities TEXT NOT NULL DEFAULT '[]', certificate_status TEXT NOT NULL DEFAULT '{}');

CREATE TABLE devices(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,token_hash TEXT NOT NULL UNIQUE,token_secret TEXT NOT NULL, deleted_at BIGINT NOT NULL DEFAULT 0);

CREATE TABLE credentials(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL REFERENCES nodes(id),device_id TEXT NOT NULL,password TEXT NOT NULL,PRIMARY KEY(node_id,device_id));

CREATE TABLE jobs(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,node_id TEXT NOT NULL REFERENCES nodes(id),kind TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created_at BIGINT NOT NULL,started_at BIGINT NOT NULL DEFAULT 0, options TEXT NOT NULL DEFAULT '{}');

CREATE UNIQUE INDEX one_active_job ON jobs(node_id) WHERE state IN ('pending','running');

CREATE TABLE events(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,node_id TEXT NOT NULL REFERENCES nodes(id),stage TEXT NOT NULL,message TEXT NOT NULL,created_at BIGINT NOT NULL);

CREATE INDEX events_node ON events(node_id,id);

CREATE TABLE daily(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL,device_id TEXT NOT NULL,start BIGINT NOT NULL,upload BIGINT NOT NULL,download BIGINT NOT NULL,PRIMARY KEY(node_id,device_id,start));

CREATE TABLE minute(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL,device_id TEXT NOT NULL,start BIGINT NOT NULL,upload BIGINT NOT NULL,download BIGINT NOT NULL,PRIMARY KEY(node_id,device_id,start));

CREATE TABLE hourly(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL,device_id TEXT NOT NULL,start BIGINT NOT NULL,upload BIGINT NOT NULL,download BIGINT NOT NULL,PRIMARY KEY(node_id,device_id,start));

CREATE TABLE lifetime(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL,device_id TEXT NOT NULL,upload BIGINT NOT NULL DEFAULT 0,download BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(node_id,device_id));

CREATE TABLE audit(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,at BIGINT NOT NULL,action TEXT NOT NULL,subject TEXT NOT NULL);

CREATE TABLE device_config(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,device_id TEXT PRIMARY KEY REFERENCES devices(id),default_node_id TEXT NOT NULL DEFAULT '',revision BIGINT NOT NULL DEFAULT 1);

CREATE TABLE assignments(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,device_id TEXT NOT NULL REFERENCES devices(id),node_id TEXT NOT NULL REFERENCES nodes(id),required_revision BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(device_id,node_id));

CREATE TABLE device_accounts(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,device_id TEXT PRIMARY KEY REFERENCES devices(id),username TEXT NOT NULL UNIQUE,password TEXT NOT NULL);

CREATE TABLE client_sessions(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),installation_id TEXT NOT NULL,client_name TEXT NOT NULL,access_hash TEXT NOT NULL UNIQUE,refresh_hash TEXT NOT NULL UNIQUE,access_expires BIGINT NOT NULL,refresh_expires BIGINT NOT NULL,last_seen BIGINT NOT NULL,created_at BIGINT NOT NULL,status TEXT NOT NULL DEFAULT '{}',revoked BIGINT NOT NULL DEFAULT 0);

CREATE INDEX client_sessions_device ON client_sessions(device_id);

CREATE TABLE spent_refresh(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,hash TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES client_sessions(id),expires BIGINT NOT NULL);

CREATE TABLE removals(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),node_id TEXT NOT NULL REFERENCES nodes(id),revision BIGINT NOT NULL,created_at BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',deadline BIGINT NOT NULL DEFAULT 0,immediate BIGINT NOT NULL DEFAULT 0);

CREATE INDEX removals_device ON removals(device_id,node_id);

CREATE TABLE removal_participants(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,removal_id TEXT NOT NULL REFERENCES removals(id),session_id TEXT NOT NULL REFERENCES client_sessions(id),PRIMARY KEY(removal_id,session_id));

CREATE TABLE rule_versions(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,hash TEXT PRIMARY KEY,version BIGINT NOT NULL UNIQUE,body BYTEA NOT NULL,created_at BIGINT NOT NULL);

CREATE TABLE servers(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,config TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,deleted_at BIGINT NOT NULL DEFAULT 0);

CREATE TABLE server_addresses(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,server_id TEXT NOT NULL REFERENCES servers(id),ip TEXT NOT NULL,created_at BIGINT NOT NULL,deleted_at BIGINT NOT NULL DEFAULT 0);

CREATE UNIQUE INDEX active_server_address ON server_addresses(server_id,ip) WHERE deleted_at=0;

CREATE TABLE node_retirements(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT PRIMARY KEY REFERENCES nodes(id),id TEXT NOT NULL UNIQUE,stopped BIGINT NOT NULL DEFAULT 0,final BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL);

CREATE TABLE node_preflights(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT PRIMARY KEY REFERENCES nodes(id),fingerprint TEXT NOT NULL,takeover BIGINT NOT NULL,created_at BIGINT NOT NULL);

CREATE TABLE node_accounting_identities(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL REFERENCES nodes(id),accounting_id TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,PRIMARY KEY(node_id,accounting_id));

CREATE TABLE settled_leases(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,node_id TEXT NOT NULL,user_id TEXT NOT NULL,accounting_id TEXT NOT NULL,upload BIGINT NOT NULL,download BIGINT NOT NULL,budget BIGINT NOT NULL,rate_version BIGINT NOT NULL);

CREATE TABLE portal_templates(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,config TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1);

CREATE TABLE portal_users(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,enabled BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,revision BIGINT NOT NULL DEFAULT 1);

CREATE TABLE portal_subscriptions(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES portal_users(id),template_id TEXT NOT NULL REFERENCES portal_templates(id),created_at BIGINT NOT NULL,expires BIGINT NOT NULL,revoked BIGINT NOT NULL DEFAULT 0,revision BIGINT NOT NULL DEFAULT 1,grant_key TEXT NOT NULL,subscription_hash TEXT NOT NULL DEFAULT '',subscription_secret TEXT NOT NULL DEFAULT '',UNIQUE(user_id,grant_key));

CREATE INDEX subscriptions_user ON portal_subscriptions(user_id,created_at);

CREATE UNIQUE INDEX subscription_tokens ON portal_subscriptions(subscription_hash) WHERE subscription_hash!='';

CREATE TABLE portal_usage(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,subscription_id TEXT PRIMARY KEY REFERENCES portal_subscriptions(id),upload BIGINT NOT NULL DEFAULT 0,download BIGINT NOT NULL DEFAULT 0,reserved BIGINT NOT NULL DEFAULT 0);

CREATE TABLE portal_requests(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES portal_users(id),template_id TEXT NOT NULL REFERENCES portal_templates(id),status TEXT NOT NULL,requested_at BIGINT NOT NULL,decided_at BIGINT NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',subscription_id TEXT NOT NULL DEFAULT '',revision BIGINT NOT NULL DEFAULT 1,request_key TEXT NOT NULL,UNIQUE(user_id,request_key));

CREATE TABLE portal_credentials(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,user_id TEXT NOT NULL REFERENCES portal_users(id),subscription_id TEXT NOT NULL REFERENCES portal_subscriptions(id),node_id TEXT NOT NULL REFERENCES nodes(id),scope TEXT NOT NULL,password_hash TEXT NOT NULL UNIQUE,password_secret TEXT NOT NULL,PRIMARY KEY(subscription_id,node_id,scope));

CREATE TABLE portal_sessions(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES portal_users(id),kind TEXT NOT NULL,client_name TEXT NOT NULL,installation_id TEXT NOT NULL DEFAULT '',access_hash TEXT NOT NULL UNIQUE,refresh_hash TEXT NOT NULL UNIQUE,csrf TEXT NOT NULL,access_expires BIGINT NOT NULL,expires BIGINT NOT NULL,created_at BIGINT NOT NULL,last_seen BIGINT NOT NULL,revoked BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT '{}',selected_subscription_id TEXT NOT NULL DEFAULT '',selection_revision BIGINT NOT NULL DEFAULT 1);

CREATE TABLE portal_spent_refresh(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,hash TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES portal_sessions(id),expires BIGINT NOT NULL);

CREATE TABLE portal_authorizations(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,challenge TEXT NOT NULL,redirect_uri TEXT NOT NULL,state TEXT NOT NULL,installation_id TEXT NOT NULL,client_name TEXT NOT NULL,expires BIGINT NOT NULL,user_id TEXT NOT NULL DEFAULT '',code_hash TEXT NOT NULL DEFAULT '',consumed BIGINT NOT NULL DEFAULT 0);

CREATE TABLE portal_leases(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,node_id TEXT NOT NULL REFERENCES nodes(id),connection_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES portal_users(id),subscription_id TEXT NOT NULL REFERENCES portal_subscriptions(id),session_id TEXT NOT NULL,revision BIGINT NOT NULL,created_at BIGINT NOT NULL,expires BIGINT NOT NULL,bandwidth BIGINT NOT NULL,budget BIGINT NOT NULL,upload BIGINT NOT NULL DEFAULT 0,download BIGINT NOT NULL DEFAULT 0,closed BIGINT NOT NULL DEFAULT 0,revoked BIGINT NOT NULL DEFAULT 0,UNIQUE(node_id,connection_id));

CREATE INDEX portal_lease_subscription ON portal_leases(subscription_id,expires,closed);

CREATE INDEX portal_lease_user ON portal_leases(user_id,session_id);

CREATE TABLE portal_rates(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,lease_id TEXT PRIMARY KEY REFERENCES portal_leases(id),version BIGINT NOT NULL DEFAULT 1,ack BIGINT NOT NULL DEFAULT 0,ceiling BIGINT NOT NULL DEFAULT 0,pending BIGINT NOT NULL DEFAULT 1);

CREATE TABLE portal_turnstile_tokens(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,hash TEXT PRIMARY KEY,expires BIGINT NOT NULL);

CREATE TABLE cloudflare_settings(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id BIGINT PRIMARY KEY CHECK(id=1),token TEXT NOT NULL,zone_id TEXT NOT NULL,zone_name TEXT NOT NULL,email TEXT NOT NULL,version BIGINT NOT NULL,updated_at BIGINT NOT NULL);

CREATE TABLE cloudflare_dns(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,node_id TEXT NOT NULL REFERENCES nodes(id),kind TEXT NOT NULL,zone_id TEXT NOT NULL,zone_name TEXT NOT NULL,record TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created_at BIGINT NOT NULL,error TEXT NOT NULL DEFAULT '');

CREATE UNIQUE INDEX node_dns_active ON cloudflare_dns(node_id) WHERE kind='A' AND state!='deleted';

CREATE TABLE certificate_accounts(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,directory TEXT PRIMARY KEY,private_key TEXT NOT NULL);

CREATE TABLE certificate_versions(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL REFERENCES nodes(id),version BIGINT NOT NULL,bundle TEXT NOT NULL,created_at BIGINT NOT NULL,PRIMARY KEY(node_id,version));

CREATE TABLE certificate_state(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT PRIMARY KEY REFERENCES nodes(id),domain TEXT NOT NULL DEFAULT '',issued_version BIGINT NOT NULL DEFAULT 0,applied_version BIGINT NOT NULL DEFAULT 0,not_before BIGINT NOT NULL DEFAULT 0,not_after BIGINT NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,failures BIGINT NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',applied_error TEXT NOT NULL DEFAULT '',reported_at BIGINT NOT NULL DEFAULT 0);

CREATE TABLE cloudflare_leases(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,name TEXT PRIMARY KEY,owner TEXT NOT NULL,expires BIGINT NOT NULL);

CREATE TABLE alerts(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,key TEXT NOT NULL UNIQUE,condition TEXT NOT NULL,status TEXT NOT NULL,acknowledged BIGINT NOT NULL DEFAULT 0,ack_by TEXT NOT NULL DEFAULT '',ack_at BIGINT NOT NULL DEFAULT 0,first_seen BIGINT NOT NULL,last_seen BIGINT NOT NULL,ended_at BIGINT NOT NULL DEFAULT 0,revision BIGINT NOT NULL DEFAULT 1,since BIGINT NOT NULL,missing_since BIGINT NOT NULL DEFAULT 0);

CREATE INDEX alerts_current ON alerts(status,acknowledged,last_seen);

CREATE TABLE alert_activity(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,alert_id TEXT NOT NULL REFERENCES alerts(id) ON DELETE CASCADE,kind TEXT NOT NULL,message TEXT NOT NULL,actor TEXT NOT NULL DEFAULT '',at BIGINT NOT NULL);

CREATE INDEX alert_activity_object ON alert_activity(alert_id,id);

CREATE TABLE alert_job_sources(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,job_id BIGINT PRIMARY KEY,created_at BIGINT NOT NULL);

CREATE TABLE node_network_quality(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
 node_id TEXT PRIMARY KEY REFERENCES nodes(id),status TEXT NOT NULL,job_id BIGINT NOT NULL,
 source_ip TEXT NOT NULL,requested_at BIGINT NOT NULL,started_at BIGINT NOT NULL DEFAULT 0,
 finished_at BIGINT NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',report_at BIGINT NOT NULL DEFAULT 0,
 report_ip TEXT NOT NULL DEFAULT '',report TEXT NOT NULL DEFAULT 'null');

CREATE TABLE native_hourly (rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
 node_id TEXT NOT NULL,device_id TEXT NOT NULL,start BIGINT NOT NULL,
 upload BIGINT NOT NULL,download BIGINT NOT NULL,uncertain BIGINT NOT NULL DEFAULT 0,
 PRIMARY KEY(node_id,device_id,start));

CREATE INDEX native_hourly_node_start ON native_hourly(node_id,start);

CREATE TABLE node_hourly_coverage (rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
 node_id TEXT PRIMARY KEY,since BIGINT NOT NULL,through BIGINT NOT NULL,CHECK(through>=since));

CREATE TABLE node_hourly_gaps (rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
 node_id TEXT NOT NULL,start BIGINT NOT NULL,"end" BIGINT NOT NULL,CHECK("end">start),PRIMARY KEY(node_id,start,"end"));

CREATE TABLE server_billing(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,server_id TEXT PRIMARY KEY REFERENCES servers(id),epoch TEXT NOT NULL,started_at BIGINT NOT NULL,anchor BIGINT NOT NULL,expires_at BIGINT NOT NULL, cycle_offset BIGINT NOT NULL DEFAULT 0);

CREATE TABLE server_renewals(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,server_id TEXT NOT NULL REFERENCES servers(id),request_id TEXT NOT NULL,payload TEXT NOT NULL,body TEXT NOT NULL,confirmed_at BIGINT NOT NULL,UNIQUE(server_id,request_id));

CREATE TABLE billing_daily(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL REFERENCES nodes(id),start BIGINT NOT NULL,upload BIGINT NOT NULL,download BIGINT NOT NULL,PRIMARY KEY(node_id,start));

CREATE TABLE billing_hourly(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,node_id TEXT NOT NULL REFERENCES nodes(id),start BIGINT NOT NULL,upload BIGINT NOT NULL,download BIGINT NOT NULL,uncertain BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(node_id,start));

CREATE UNIQUE INDEX device_accounts_username_ci ON device_accounts(lower(username));

CREATE UNIQUE INDEX portal_users_email_ci ON portal_users(lower(email));

CREATE INDEX nodes_server ON nodes ((config::jsonb->>'serverId'));

CREATE INDEX portal_sessions_user_active ON portal_sessions(user_id,revoked,expires,last_seen DESC);

CREATE INDEX portal_lease_node ON portal_leases(node_id,closed);

CREATE INDEX daily_time ON daily(start);

CREATE INDEX minute_time ON minute(start);

CREATE INDEX hourly_time ON hourly(start);

INSERT INTO metadata(key,value) VALUES('schema_version','5'),('postgres_schema_version','1'),('portal_enabled','false'),('portal_registration','false'),('alerts_migrated','1');
